1	// Basket rules, free of Hono and of file I/O: the store and the catalog come in as values.
2	import type { AddBasketItem, BasketLine, BasketResponse, StoredBasket } from "@organic/shared";
3	import type { CatalogService } from "./catalog";
4	import type { BasketStore } from "./store/baskets";
5	
6	const MAX_QUANTITY = 99;
7	
8	/** A miss is a value, not an exception: the route maps it to 404 without a try/catch. */
9	export type BasketResult =
10	  | { ok: true; basket: BasketResponse }
11	  | { ok: false; error: "Product not found" | "Basket item not found" };
12	
13	export interface BasketServiceOptions {
14	  store: BasketStore;
15	  catalog: Pick<CatalogService, "findProduct">;
16	  now: () => number;
17	}
18	
19	export interface BasketService {
20	  get(id: string): Promise<BasketResponse>;
21	  addItem(id: string, item: AddBasketItem): Promise<BasketResult>;
22	  updateItem(id: string, productId: string, quantity: number): Promise<BasketResult>;
23	  removeItem(id: string, productId: string): Promise<BasketResult>;
24	  clear(id: string): Promise<BasketResponse>;
25	}
26	
27	const NO_ITEMS: StoredBasket["items"] = [];
28	
29	export function createBasketService({ store, catalog, now }: BasketServiceOptions): BasketService {
30	  const timestamp = () => new Date(now()).toISOString();
31	
32	  /** Joins every stored line with the catalog; totals ignore lines whose product is gone. */
33	  async function toResponse(id: string, stored: StoredBasket | undefined): Promise<BasketResponse> {
34	    const items: BasketLine[] = await Promise.all(
35	      (stored?.items ?? []).map(async (line) => ({
36	        productId: line.productId,
37	        quantity: line.quantity,
38	        product: (await catalog.findProduct(line.productId)) ?? null,
39	      })),
40	    );
41	    const totals = items.reduce(
42	      (acc, line) =>
43	        line.product
44	          ? { count: acc.count + line.quantity, sum: acc.sum + line.product.price * line.quantity }
45	          : acc,
46	      { count: 0, sum: 0 },
47	    );
48	    // Kopiykas: a price like 1.1 ₴ must not leak binary float noise (1.1 × 3 = 3.3000000000000003) into the
49	    // response. Integer prices are unchanged by the rounding.
50	    return { id, items, totals: { ...totals, sum: Math.round(totals.sum * 100) / 100 } };
51	  }
52	
53	  return {
54	    // A GET never creates a file entry: an unknown id simply reads as the empty basket.
55	    async get(id) {
56	      return toResponse(id, await store.get(id));
57	    },
58	
59	    async addItem(id, { productId, quantity }) {
60	      // Resolved before the write, so a 404 leaves the basket untouched.
61	      const product = await catalog.findProduct(productId);
62	      if (!product) return { ok: false, error: "Product not found" };
63	      const updatedAt = timestamp();
64	      const stored = await store.update(id, (current) => {
65	        const items = current?.items ?? NO_ITEMS;
66	        const existing = items.find((line) => line.productId === productId);
67	        return {
68	          updatedAt,
69	          items: existing
70	            ? items.map((line) =>
71	                line.productId === productId
72	                  ? { ...line, quantity: Math.min(MAX_QUANTITY, line.quantity + quantity) }
73	                  : line,
74	              )
75	            : [...items, { productId, quantity, addedAt: updatedAt }],
76	        };
77	      });
78	      return { ok: true, basket: await toResponse(id, stored) };
79	    },
80	
81	    // The line must still be there when the write happens, so the check lives inside the queued update:
82	    // a concurrent clear or remove can no longer slip between a separate read and the write.
83	    async updateItem(id, productId, quantity) {
84	      const updatedAt = timestamp();
85	      const stored = await store.update(id, (basket) => {
86	        const items = basket?.items ?? NO_ITEMS;
87	        if (!items.some((line) => line.productId === productId)) return undefined;
88	        return {
89	          updatedAt,
90	          items: items.map((line) => (line.productId === productId ? { ...line, quantity } : line)),
91	        };
92	      });
93	      if (!stored) return { ok: false, error: "Basket item not found" };
94	      return { ok: true, basket: await toResponse(id, stored) };
95	    },
96	
97	    async removeItem(id, productId) {
98	      const updatedAt = timestamp();
99	      const stored = await store.update(id, (basket) => {
100	        const items = basket?.items ?? NO_ITEMS;
101	        if (!items.some((line) => line.productId === productId)) return undefined;
102	        return { updatedAt, items: items.filter((line) => line.productId !== productId) };
103	      });
104	      if (!stored) return { ok: false, error: "Basket item not found" };
105	      return { ok: true, basket: await toResponse(id, stored) };
106	    },
107	
108	    async clear(id) {
109	      const stored = await store.update(id, () => ({ updatedAt: timestamp(), items: [] }));
110	      return toResponse(id, stored);
111	    },
112	  };
113	}
114

